def total_party_health(party):
    total = 0
    for member in party:
        total = total + member["health"]
    return total

def numbered_roster(party):
    lines = []
    for index in range(len(party)):
        member = party[index]
        lines.append(f"{index + 1}. {member['name']} — {member['health']} HP")
    return lines
